void setup();
void loop();
// Lab internal LED, Listing 2: non-blocking blink (the lab's code, unchanged)
const unsigned long PERIOD = 1000;   // ms between toggles
unsigned long previous = 0;
bool ledOn = false;

void setup() { pinMode(LED_BUILTIN, OUTPUT); }

void loop() {
  unsigned long now = millis();
  if (now - previous >= PERIOD) {
    previous = now;
    ledOn = !ledOn;
    digitalWrite(LED_BUILTIN, ledOn ? HIGH : LOW);
  }
  // the CPU is free here
}
